(function(){
 'use strict';
 const main=document.querySelector('#main');
 const key='one-bite-science-v1';
 const info={diffusion:{title:'分子漫游',en:'MOLECULAR WANDER',tag:'观察 · 预测',time:'约 3 分钟',desc:'打开一道隔板，看随机运动怎样创造有方向的变化。',badge:'扩散观察员',symbol:'✳',color:'var(--accent)'},emulsion:{title:'乳化工坊',en:'EMULSION STUDIO',tag:'调配 · 对照',time:'约 4 分钟',desc:'水和油能一起待多久？搅拌、界面与小液滴，等你来探索。',badge:'界面探索家',symbol:'◉',color:'var(--coral)'},evidence:{title:'证据侦探',en:'EVIDENCE DETECTIVE',tag:'推理 · 判断',time:'约 5 分钟',desc:'一张图、一组数字、一个结论。发现看似合理背后的跳步。',badge:'证据侦探',symbol:'⌕',color:'var(--blue)'}};
 let record={},storageOK=true,cleanup=null,toastTimer;
 try{const data=JSON.parse(localStorage.getItem(key)||'{}');for(const id of Object.keys(info)){const v=data?.[id];if(v&&Number.isFinite(v.score)&&Number.isFinite(v.maxScore)&&v.maxScore>0&&v.score>=0&&v.score<=v.maxScore&&typeof v.date==='string')record[id]=v;}}catch{storageOK=false;}
 function esc(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
 function save(){try{localStorage.setItem(key,JSON.stringify(record));}catch{storageOK=false;}}
 function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4500);}
 function updateCount(){document.querySelector('#badge-count').textContent=Object.keys(record).length;}
 function complete(result){if(!result||!info[result.game]||!Number.isFinite(result.score)||!Number.isFinite(result.maxScore)||result.maxScore<=0)return;const old=record[result.game];const score=Math.max(0,Math.min(result.score,result.maxScore));const now=new Date().toISOString();const isBetter=!old||score/result.maxScore>old.score/old.maxScore;record[result.game]={score:isBetter?score:old.score,maxScore:isBetter?result.maxScore:old.maxScore,date:isBetter?now:old.date,lastPlayed:now,plays:(old?.plays||0)+1};save();updateCount();toast((old?'探索记录已更新':'解锁徽章：'+info[result.game].badge)+(storageOK?'':'（当前浏览器无法保存，记录仅保留到关闭页面）'));}
 function art(id){if(id==='diffusion')return `<svg viewBox="0 0 340 180" aria-hidden="true"><rect x="65" y="25" width="210" height="130" rx="24" fill="#14251e" stroke="#7eab77" stroke-width="2"/><path d="M170 25v45m0 40v45" stroke="#9fc490" stroke-width="3" stroke-dasharray="5 4"/><g fill="#b8ee81"><circle cx="91" cy="55" r="10"/><circle cx="125" cy="83" r="8"/><circle cx="98" cy="120" r="11"/><circle cx="148" cy="126" r="6"/><circle cx="147" cy="52" r="5"/><circle cx="197" cy="95" r="10"/></g><g fill="#f3a98f"><circle cx="234" cy="52" r="9"/><circle cx="244" cy="113" r="11"/><circle cx="207" cy="134" r="6"/><circle cx="199" cy="51" r="5"/><circle cx="137" cy="105" r="5"/></g><path d="M150 89h28l-5-5m5 5-5 5" fill="none" stroke="#eef2d7" stroke-width="2"/></svg>`;
 if(id==='emulsion')return `<svg viewBox="0 0 340 180" aria-hidden="true"><path d="M90 30h160l-12 115a12 12 0 0 1-12 10H114a12 12 0 0 1-12-10Z" fill="#1f2a23" stroke="#cfbd8c" stroke-width="2"/><path d="M99 77q35-14 70 0t72 0l-6 65q-1 10-11 10H116q-10 0-11-10Z" fill="#b3c6b4" opacity=".3"/><g fill="#f3a98f" stroke="#e5c7a6" stroke-width="3"><circle cx="132" cy="102" r="15"/><circle cx="194" cy="119" r="21"/><circle cx="210" cy="78" r="10"/><circle cx="150" cy="135" r="6"/><circle cx="165" cy="87" r="7"/></g><path d="M170 15c-10 13-14 19-14 25a14 14 0 0 0 28 0c0-6-4-12-14-25Z" fill="#b8ee81"/><path d="M115 40v20" stroke="#ffffff55" stroke-width="4" stroke-linecap="round"/></svg>`;
 return `<svg viewBox="0 0 340 180" aria-hidden="true"><g transform="rotate(-8 145 90)"><rect x="80" y="25" width="140" height="135" rx="15" fill="#d9e7da"/><path d="M100 48h58m-58 14h85" stroke="#718b80" stroke-width="5" stroke-linecap="round"/><rect x="103" y="100" width="16" height="35" rx="3" fill="#7a9c86"/><rect x="129" y="84" width="16" height="51" rx="3" fill="#a3ba81"/><rect x="155" y="94" width="16" height="41" rx="3" fill="#db987c"/></g><circle cx="220" cy="84" r="39" fill="#a5cfe433" stroke="#a5cfe4" stroke-width="9"/><path d="m248 115 28 33" stroke="#a5cfe4" stroke-width="14" stroke-linecap="round"/><path d="m206 83 10 10 19-22" fill="none" stroke="#e5f2e7" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/></svg>`;}
 function home(){main.innerHTML=`<div class="page-wrap page-enter"><section class="hero" aria-labelledby="home-title"><div class="hero-copy"><span class="eyebrow">好奇心游乐场 · VOL. 02</span><h1 id="home-title">把好奇心，<br>放进<em>实验室。</em></h1><p class="hero-desc">一点生活，一点科学，还有一点意想不到。<br>动动手，让看不见的原理变成看得见的发现。</p><div class="hero-actions"><a class="btn primary arrow" href="#diffusion">开始第一场探索</a><span class="tiny-note">实验 · 游戏 · 小发现</span></div></div><div class="hero-art"><img src="assets/lab-hero.png" alt="薄荷绿玻璃烧瓶里漂浮着彩色小球，旁边摆着小碗和试管的幻想实验室插画" fetchpriority="high"><div class="floating-label">TODAY'S INGREDIENT<strong>CURIOSITY</strong></div><span class="art-note">好奇心 × 一点点想象</span></div></section><section aria-labelledby="choose-title"><div class="section-top"><div><span class="eyebrow">PICK AN EXPERIMENT</span><h2 id="choose-title">今天，想发现什么？</h2></div><p>不用准备知识。带上一个「为什么」就好。</p></div><div class="experiment-list">${Object.entries(info).map(([id,g],i)=>`<a class="experiment-card" href="#${id}" aria-label="进入${g.title}，${g.time}"><div class="card-art art-${id}"><span class="number">EXPERIMENT / 0${i+1}</span>${art(id)}</div><div class="card-body"><div class="card-meta"><span>${g.tag}</span><span>${g.time}</span></div><h3>${g.title}</h3><p>${g.desc}</p><div class="card-bottom"><span>${record[id]?'已探索 · 再玩一次':'进入实验'}</span><span class="round-arrow" aria-hidden="true">↗</span></div></div></a>`).join('')}</div></section><aside class="passport-banner"><div><strong>每一次「原来如此」，都值得收藏。</strong><p>完成探索，收集 3 枚科学徽章。你的发现会留在探索手记里。</p></div><a href="#journal" class="passport-link"><span class="passport-badges" aria-hidden="true">${Object.entries(info).map(([id,g])=>`<span class="${record[id]?'earned':''}">${g.symbol}</span>`).join('')}</span><span class="tiny-note">查看手记 ↗</span></a></aside><section class="new-discoveries" aria-labelledby="new-discoveries-title"><div class="section-top"><div><span class="eyebrow">PLAY A LITTLE FURTHER</span><h2 id="new-discoveries-title">再往前玩一点。</h2></div><p>给双手一个挑战，也给直觉一个新视角。</p></div><div class="discovery-grid"><a href="arcade.html" class="discovery-card courier-card"><div class="discovery-picture"><img src="assets/micro-courier.png" alt="奶白色小机器人拿着绿球，站在深绿色立体迷宫中的幻想游戏插画" loading="lazy"><span class="discovery-badge">NEW / 操作闯关</span></div><div class="discovery-copy"><span class="eyebrow">MICRO COURIER</span><h3>微观快递</h3><p>收集、搬运、穿过迷宫。8 个小关卡，考验路线规划和你的操作。虚构益智玩法，可选择不限时练习。</p><span class="discovery-go">开始冒险 <b aria-hidden="true">↗</b></span></div></a><a href="data-lab.html" class="discovery-card data-card"><div class="discovery-picture data-picture"><span class="discovery-badge">NEW / 数据实验</span><div class="data-art" aria-hidden="true"><span class="chart-number">10 → 11</span><div class="chart-bars"><i style="height:100px"><span>10</span></i><i style="height:110px"><span>11</span></i></div><span class="chart-finding">变化了多少？ <strong>+10%</strong></span></div></div><div class="discovery-copy"><span class="eyebrow">DATA MAGNIFIER</span><h3>数据放大镜</h3><p>拖动纵轴，改变一个极端值，再做一组抽样。让数据自己说清楚，眼睛到底被骗在哪里。</p><span class="discovery-go">打开实验台 <b aria-hidden="true">↗</b></span></div></a></div></section><a class="design-banner" href="design-lab.html"><div class="design-banner-art" aria-hidden="true"><span>问题</span><i>→</i><span>比较</span><i>→</i><span>证据</span></div><div><span class="eyebrow">BUILD YOUR OWN EXPERIMENT</span><h3>先设计，再下结论。</h3><p>四种虚构场景，练习挑选变量、对照、重复与指标。把你的方案变成一张设计卡。</p></div><b aria-hidden="true">↗</b></a><section class="more-science" aria-label="更多探索"><a class="more-item" href="builder.html"><span class="more-icon" aria-hidden="true">▦</span><div><span class="eyebrow">MAKE IT PLAYABLE</span><h3>画一个你自己的关卡。</h3><p>改地图、检查路线、亲自试玩。把想法做成能玩的东西。</p></div><span aria-hidden="true">↗</span></a><a class="more-item" href="video.html"><span class="more-icon" aria-hidden="true">▶</span><div><span class="eyebrow">WATCH & KEEP</span><h3>三分钟，换三个看法。</h3><p>图表、平均数与概率。三集中文旁白短片，可保存观看。</p></div><span aria-hidden="true">↗</span></a><a class="more-item" href="film.html"><span class="more-icon" aria-hidden="true">▷</span><div><span class="eyebrow">60 SECOND FILM</span><h3>均匀了，分子为什么还不停？</h3><p>一段可以暂停、回看、拖动的科学小短片。</p></div><span aria-hidden="true">↗</span></a><a class="more-item" href="cards.html"><span class="more-icon" aria-hidden="true">▧</span><div><span class="eyebrow">30 POCKET CARDS</span><h3>把一个问题，装进口袋。</h3><p>分子、乳液、证据，30 张知识卡慢慢看。</p></div><span aria-hidden="true">↗</span></a><a class="more-item" href="assets/exploration-handbook.pdf" download="一口科学_中文探究手册.pdf"><span class="more-icon" aria-hidden="true">▤</span><div><span class="eyebrow">12 PAGE FIELD GUIDE</span><h3>把实验台，搬到纸上。</h3><p>12 页可打印探究手册，含练习、答案与记录表。</p></div><span aria-hidden="true">↓</span></a></section></div>`;}
 function play(id){const g=info[id];main.innerHTML=`<div class="page-wrap page-enter"><header class="play-header"><div class="breadcrumb"><a href="#home">← 返回游乐场</a><span>/</span><span>${g.title}</span></div><div class="game-heading"><div><span class="eyebrow">${g.en}</span><h1>${g.title}</h1><p>${g.desc}</p></div><nav class="game-tabs" aria-label="切换实验">${Object.entries(info).map(([k,x])=>`<a href="#${k}" class="${k===id?'active':''}" ${k===id?'aria-current="page"':''}>${x.title}</a>`).join('')}</nav></div></header><section id="game-mount" class="game-mount" aria-label="${g.title}互动区域"></section><div class="learning-path"><a href="#journal">我的探索手记 ↗</a><a href="#${Object.keys(info)[(Object.keys(info).indexOf(id)+1)%3]}">下一场：${info[Object.keys(info)[(Object.keys(info).indexOf(id)+1)%3]].title} →</a></div></div>`;const mount=window.LabModules?.[id]?.mount;if(mount){try{cleanup=mount(document.querySelector('#game-mount'),{onComplete:complete});}catch(e){document.querySelector('#game-mount').innerHTML='<div class="empty-error"><h2>这个实验暂时没有加载成功。</h2><p>请刷新重试，或先进入另一场探索。</p><a class="btn" href="#home">回到游乐场</a></div>';console.error(e);}}else document.querySelector('#game-mount').innerHTML='<div class="empty-error"><h2>实验还在准备中。</h2><p>稍后刷新页面，就可以开始探索。</p></div>';}
 function journal(){main.innerHTML=`<div class="page-wrap page-enter"><header class="journal-intro"><span class="eyebrow">YOUR FIELD NOTES</span><h1>把发现，装进口袋。</h1><p>已经收集 ${Object.keys(record).length} / 3 枚徽章。每次完成探索，都会留下新的足迹。</p></header><div class="journal-grid">${Object.entries(info).map(([id,g])=>{const r=record[id];return `<article class="badge-card ${r?'earned':''}"><div class="medal" aria-hidden="true">${g.symbol}</div><span class="eyebrow">${r?'已解锁':'等待发现'}</span><h2>${g.badge}</h2><p>${r?'你已完成「'+g.title+'」。'+(id==='emulsion'?'再次调配，比较不同条件。':'再次探索可以刷新最高成绩。'):'完成「'+g.title+'」，让这枚徽章亮起来。'}</p><div class="badge-stat"><span>${id==='emulsion'?'完成挑战':'最高答题成绩'}</span><strong>${r?esc(r.score)+' / '+esc(r.maxScore):'—'}</strong></div>${r?`<p>已完成 ${esc(r.plays||1)} 次 · 最近探索 ${esc(new Date(r.lastPlayed||r.date).toLocaleDateString('zh-CN'))}</p>`:''}<a class="btn ${r?'':'primary'} arrow" href="#${id}">${r?'再探索一次':'去解锁'}</a></article>`;}).join('')}</div><div class="journal-actions"><button class="btn" id="download-record" ${Object.keys(record).length?'':'disabled'}>导出我的手记 ↓</button><p>${storageOK?'记录保存在当前浏览器；下载一份，也可以把发现随身带走。':'当前浏览器无法保存记录，关闭页面前可以下载手记。'}</p></div></div>`;document.querySelector('#download-record').addEventListener('click',()=>{const lines=['一口科学 · 我的探索手记','导出日期：'+new Date().toLocaleString('zh-CN'),''];for(const [id,v]of Object.entries(record)){lines.push(info[id].badge+'｜'+info[id].title,(id==='emulsion'?'完成挑战：':'最高答题成绩：')+v.score+' / '+v.maxScore,'完成次数：'+(v.plays||1),'');}lines.push('以上为教学游戏记录，不代表专业知识评估或实验测量。');const blob=new Blob(['\ufeff'+lines.join('\r\n')],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='一口科学_探索手记.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('手记已准备下载');});}
 function route(){if(typeof cleanup==='function')cleanup();cleanup=null;let id=location.hash.slice(1)||'home';if(!['home','journal',...Object.keys(info)].includes(id))id='home';document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===id;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(id==='home')home();else if(id==='journal')journal();else play(id);document.title=(info[id]?.title||(id==='journal'?'探索手记':'好奇心游乐场'))+' · 一口科学';window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});updateCount();}
 const dialog=document.querySelector('#about-dialog');for(const id of ['about-open','footer-about'])document.getElementById(id).addEventListener('click',()=>dialog.showModal());for(const id of ['about-close','about-done'])document.getElementById(id).addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
 document.querySelector('.skip-link').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView({block:'start'});});
 window.addEventListener('hashchange',route);route();
})();

